-- Athena saved query (Product_B2C_Intl)
-- ID: 90a320f8-7662-447d-a8ab-8a1850c0d12e
-- Name: User Profiling RUM - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH search_data AS ( -- Step 1: Grab search data along with your dimensions SELECT mri_session_id, mri_client_id, channel, os AS os,user_type FROM user_interaction.search_details WHERE __time >= TIMESTAMP '2026-04-20 00:00:00' AND __time < TIMESTAMP '2026-04-21 00:00:00' AND country = 'IND' AND tp_channel = 'INVALID' ), distinct_search_clients AS ( -- Step 2: Clean list of client IDs to filter the RUM dataset efficiently SELECT DISTINCT mri_client_id FROM search_data ), filtered_rum AS ( -- Step 3: Collapse RUM rows to 1 per client and grab their user_type SELECT r.mriclientid, MAX(CASE WHEN r.yob IS NOT NULL THEN 1 ELSE 0 END) AS has_yob, MAX(CASE WHEN r.gender IS NOT NULL AND r.gender <> '' THEN 1 ELSE 0 END) AS has_gender, MAX(CASE WHEN r.phone IS NOT NULL AND r.phone <> '' THEN 1 ELSE 0 END) AS has_phone, MAX(CASE WHEN r.email IS NOT NULL AND r.email <> '' THEN 1 ELSE 0 END) AS has_email FROM rum.rum_piddetails r INNER JOIN distinct_search_clients d ON r.mriclientid = d.mri_client_id GROUP BY r.mriclientid ), aggregated_metrics AS ( -- Step 4: Join tables and group by the requested granular dimensions SELECT s.channel, s.os, upper(s.user_type) AS user_type, COUNT(DISTINCT s.mri_session_id) AS total_sessions_in_search, COUNT(DISTINCT s.mri_client_id) AS total_distinct_clients_in_search, COUNT(DISTINCT r.mriclientid) AS total_distinct_clients_joined, COUNT(DISTINCT CASE WHEN r.has_yob = 1 THEN r.mriclientid END) AS total_joined_with_yob, COUNT(DISTINCT CASE WHEN r.has_gender = 1 THEN r.mriclientid END) AS total_joined_with_gender, COUNT(DISTINCT CASE WHEN r.has_phone = 1 THEN r.mriclientid END) AS total_joined_with_phone, COUNT(DISTINCT CASE WHEN r.has_email = 1 THEN r.mriclientid END) AS total_joined_with_email FROM search_data s LEFT JOIN filtered_rum r ON s.mri_client_id = r.mriclientid GROUP BY 1,2,3 ) -- Step 5: Output all segments with their respective matching percentages SELECT channel, os, user_type, total_sessions_in_search, total_distinct_clients_in_search, total_distinct_clients_joined, ROUND(100.0 * total_distinct_clients_joined / NULLIF(total_distinct_clients_in_search, 0), 2) AS pct_users_found_in_rum, ROUND(100.0 * total_joined_with_yob / NULLIF(total_distinct_clients_in_search, 0), 2) AS pct_searching_users_with_age, ROUND(100.0 * total_joined_with_gender / NULLIF(total_distinct_clients_in_search, 0), 2) AS pct_searching_users_with_gender, ROUND(100.0 * total_joined_with_phone / NULLIF(total_distinct_clients_in_search, 0), 2) AS pct_searching_users_with_phone, ROUND(100.0 * total_joined_with_email / NULLIF(total_distinct_clients_in_search, 0), 2) AS pct_searching_users_with_email FROM aggregated_metrics ORDER BY total_sessions_in_search DESC; SELECT * FROM rum.rum_piddetails LIMIT 100
